import { useState, useEffect } from 'react';

/** Polls a fetch function every intervalMs milliseconds. */
export function usePolling<T>(fetchFn: () => Promise<T>, intervalMs: number) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    fetchFn().then(setData).catch(setError);
    // BUG: interval is set but never cleared
    const id = setInterval(() => {
      fetchFn().then(setData).catch(setError);
    }, intervalMs);
    // Should return () => clearInterval(id);
  }, [fetchFn, intervalMs]);

  return { data, error };
}

