import { renderHook, act } from '@testing-library/react';
import { useWindowSize } from './useWindowSize';
import { usePolling } from './usePolling';

test('useWindowSize returns initial size', () => {
  const { result } = renderHook(() => useWindowSize());
  expect(result.current.width).toBeDefined();
  expect(result.current.height).toBeDefined();
});

test('useWindowSize cleans up on unmount', () => {
  const addSpy = jest.spyOn(window, 'addEventListener');
  const removeSpy = jest.spyOn(window, 'removeEventListener');
  const { unmount } = renderHook(() => useWindowSize());
  unmount();
  // After unmount, removeEventListener should be called
  expect(removeSpy).toHaveBeenCalledWith('resize', expect.any(Function));
  addSpy.mockRestore();
  removeSpy.mockRestore();
});

test('usePolling returns fetched data', async () => {
  const fetchFn = jest.fn().mockResolvedValue({ items: [1, 2, 3] });
  const { result } = renderHook(() => usePolling(fetchFn, 10000));
  await act(async () => {});
  expect(result.current.data).toEqual({ items: [1, 2, 3] });
});

test('usePolling clears interval on unmount', () => {
  const clearSpy = jest.spyOn(global, 'clearInterval');
  const fetchFn = jest.fn().mockResolvedValue({});
  const { unmount } = renderHook(() => usePolling(fetchFn, 10000));
  unmount();
  expect(clearSpy).toHaveBeenCalled();
  clearSpy.mockRestore();
});
